create or replace function public.admit_schoolpro_applicant(p_application uuid) returns uuid language plpgsql security definer set search_path='' as $$declare a public.schoolpro_admissions;sid uuid;adm text;begin select * into a from public.schoolpro_admissions where id=p_application;if a.id is null then raise exception 'Application not found';end if;if not(public.schoolpro_member_can_manage(a.school_id) or exists(select 1 from public.schoolpro_members m where m.school_id=a.school_id and m.user_id=auth.uid() and m.role::text in('registrar','admissions_officer'))) then raise exception 'Not authorized';end if;if a.admitted_student_id is not null then return a.admitted_student_id;end if;adm:=coalesce(a.application_number,'ADM-'||upper(substr(replace(a.id::text,'-',''),1,8)));insert into public.schoolpro_students(school_id,admission_number,first_name,last_name,class_name,gender,guardian_name,guardian_phone,status) values(a.school_id,adm,coalesce(nullif(a.first_name,''),split_part(a.applicant_name,' ',1)),coalesce(nullif(a.last_name,''),'Student'),coalesce(a.class_applied,'Unassigned'),a.gender,a.guardian_name,a.guardian_contact,'active') returning id into sid;update public.schoolpro_admissions set status='admitted',reviewed_by=auth.uid(),reviewed_at=now(),admitted_student_id=sid where id=a.id;return sid;end$$;
create or replace function public.finalize_schoolpro_enrollment(p_application uuid) returns uuid language plpgsql security definer set search_path='' as $$declare a public.schoolpro_admissions;sid uuid;begin select * into a from public.schoolpro_admissions where id=p_application for update;if a.id is null then raise exception 'Application not found';end if;if not(public.schoolpro_member_can_manage(a.school_id) or exists(select 1 from public.schoolpro_members m where m.school_id=a.school_id and m.user_id=auth.uid() and m.role::text in('registrar','admissions_officer'))) then raise exception 'Not authorized';end if;if not exists(select 1 from public.schoolpro_admission_offers o join public.schoolpro_admission_acceptances x on x.application_id=o.application_id where o.application_id=a.id and o.status='accepted' and o.accepted_at is not null and x.terms_accepted=true) then raise exception 'A valid admission offer has not been accepted';end if;sid:=public.admit_schoolpro_applicant(a.id);update public.schoolpro_admissions set enrollment_status='enrolled',enrolled_at=now() where id=a.id;return sid;end$$;
create or replace function public.queue_schoolpro_email(p_school uuid,p_email text,p_name text,p_template text,p_subject text,p_payload jsonb default '{}'::jsonb) returns uuid language plpgsql security definer set search_path='' as $$declare eid uuid;begin if auth.uid() is null then raise exception 'Authentication required';end if;if not(public.schoolpro_member_can_manage(p_school) or exists(select 1 from public.schoolpro_members m where m.school_id=p_school and m.user_id=auth.uid() and m.role::text in('registrar','admissions_officer','teacher','class_teacher','exam_officer','accountant','bursar'))) then raise exception 'Not authorized';end if;if p_email is null or position('@' in p_email)=0 then raise exception 'Valid email required';end if;insert into public.schoolpro_email_queue(school_id,recipient_email,recipient_name,template_key,subject,payload) values(p_school,lower(trim(p_email)),p_name,p_template,p_subject,coalesce(p_payload,'{}'::jsonb)) returning id into eid;return eid;end$$;